rDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.0\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/121212165/dsh-plugin-ide-hub/issues\"\n  },\n  \"icon\": \"./icon.svg\"\n}\n"
